def solve2(inp):
    bg=Counter(x for r in inp for x in r).most_common(1)[0][0]
    objs=objects(inp,bg)
    # majority voting: each object stamped at its top-left origin; count votes per cell offset
    counts=Counter()
    for o in objs:
        mr=min(r for r,_ in o); mc=min(c for _,c in o)
        H=max(r for r,_ in o)-mr+1; W=max(c for _,c in o)-mc+1
        m=[[0]*W for _ in range(H)]
        for r,c in o: m[r-mr][c-mc]=1
        counts[(H,W)]=counts.get((H,W),0)+1
    (H,W),n=counts.most_common(1)[0]
    tot=[ [0]*W for _ in range(H) ]
    for o in objs:
        mr=min(r for r,_ in o); mc=min(c for _,c in o)
        m=[[0]*W for _ in range(H)]
        for r,c in o:
            rr,cc=r-mr,c-mc
            if rr<H and cc<W: m[rr][cc]=1
        for rr in range(H):
            for cc in range(W): tot[rr][cc]+=m[rr][cc]
    res=[[7 if tot[r][c]>=n//2 else 0 for c in range(W)] for r in range(H)]
    return res
